// One row per sheet lead, carrying only what identifies it and the date we are reconciling to.
// Nothing here is invented: a row whose LEAD RECEIVED cannot be read keeps lead_received = null and
// is dropped by the SQL, never replaced with a plausible-looking date.
const meta  = $('Resolve Client').first().json || {};
const loop  = $('Loop Over Items').first().json || {};
const apply = String(($('Config').first().json || {}).apply ?? 'false');
const NO_CLIENT = '00000000-0000-0000-0000-000000000000';
const s = v => { const t = String(v ?? '').trim(); return t === '' ? null : t; };
const pad = n => String(n).padStart(2, '0');
// Client sheets do not agree on date locale. Detect the order from the WHOLE tab — a value > 12 in
// one position settles it — instead of assuming per row. Assuming D/M/Y is what would silently turn
// 05/03/2026 into 5 March; the 2026-07-22 import hit exactly that on 9 of 42 workbooks.
const detectOrder = vals => {
  // ONLY slash values vote. An ISO value is self-describing, so it has no opinion about whether
  // 06/03 is June or March — and letting it vote is not harmless: TouchlessFreaks v2 mixes 126 ISO
  // rows (70 with day > 12) with 78 M/D/Y slash rows (42 decisive). The ISO majority flipped the tab
  // to D/M/Y and proposed swapping day and month on 28 leads that were already correct.
  let dmy = 0, mdy = 0, slash = 0;
  for (const v of vals) {
    const m = String(v ?? '').trim().match(/^(\d{1,2})[./](\d{1,2})[./]\d{4}/);
    if (!m) continue;
    slash++;
    if (Number(m[1]) > 12) dmy++;
    if (Number(m[2]) > 12) mdy++;
  }
  if (mdy > dmy) return 'mdy';
  if (dmy > mdy) return 'dmy';
  // No evidence either way. ISO values stay readable, slash values do not — and a tab too small to
  // settle its own format is exactly where guessing costs the most: EvidencePrime has two dated
  // rows, and reading 07/02/2026 as D/M/Y proposed moving a lead from 2 July back to 7 February.
  return slash > 0 ? 'ambiguous' : 'dmy';
};
const isoDate = (v, order) => {
  const t = String(v ?? '').trim();
  let m = t.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) { let a = Number(m[2]), b = Number(m[3]);
    let mo = order === 'mdy' ? a : (a > 12 ? b : a);
    let d  = order === 'mdy' ? b : (a > 12 ? a : b);
    if (mo > 12) { const t2 = mo; mo = d; d = t2; }
    return (mo >= 1 && mo <= 12 && d >= 1 && d <= 31) ? `${m[1]}-${pad(mo)}-${pad(d)}` : null; }
  m = t.match(/^(\d{1,2})[./](\d{1,2})[./](\d{4})/);
  if (m) { if (order === 'ambiguous') return null;
    let d = Number(m[1]), mo = Number(m[2]);
    if (order === 'mdy') { const t2 = d; d = mo; mo = t2; }
    if (mo > 12 && d <= 12) { const t2 = mo; mo = d; d = t2; }
    return (mo >= 1 && mo <= 12 && d >= 1 && d <= 31) ? `${m[3]}-${pad(mo)}-${pad(d)}` : null; }
  return null;
};
const order = detectOrder($input.all().map(i => (i.json || {})['LEAD RECEIVED']));
const rows = [];
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.error || (j.message && Object.keys(j).length <= 3)) continue;
  if (!j['E-MAIL'] && !j['FULL NAME'] && !j['LEAD RECEIVED']) continue;
  rows.push({
    email: s(j['E-MAIL']),
    full_name: s(j['FULL NAME']),
    company: s(j['COMPANY NAME']),
    lead_received: isoDate(j['LEAD RECEIVED'], order),
  });
}
// A client that resolved to nothing still emits a row: an empty branch ends splitInBatches early
// and the run reports success having covered a fraction of the clients.
if (!meta.client_id) {
  return [{ json: { client_id: NO_CLIENT, client: loop.client || 'unresolved', apply,
                    sheet_rows: 0, date_order: 'n/a', payload: '[]' } }];
}
return [{ json: { client_id: meta.client_id, client: meta.name, apply,
                  sheet_rows: rows.length, date_order: order, payload: JSON.stringify(rows) } }];

// CS PDCA is the client index: col_4 is the client's own Leads spreadsheet id, col_5 the Bison
// workspace id we resolve client_id from. A row without both cannot be read and is skipped.
const out = [];
for (const i of $input.all()) {
  const j = i.json;
  const doc = String(j.col_4 ?? '').trim();
  const ws  = String(j.col_5 ?? '').trim();
  const name = String(j['Customer Success'] ?? '').trim();
  if (!doc || doc.length < 30 || !ws) continue;
  out.push({ json: { client: name, ws, doc } });
}
return out;

// One row for the whole run. Per-client detail is kept only where there is something to look at —
// a move, an ambiguity or an error — so a clean client does not hide the ones that need a human.
const rows = $input.all().map(i => i.json || {});
const num = v => Number(v ?? 0);
const errors = rows.filter(r => r.error || !r.client_id);
const ok = rows.filter(r => r.client_id);
const total = key => ok.reduce((a, r) => a + num(r[key]), 0);
const perClient = ok
  .filter(r => num(r.to_move) > 0 || num(r.ambiguous_leads) > 0 || num(r.sheet_rows_no_date) > 0
            || r.date_order === 'ambiguous')
  .map(r => ({
    client: r.client, date_order: r.date_order, to_move: num(r.to_move), aimfox: num(r.to_move_aimfox),
    moved: num(r.leads_moved), replies_moved: num(r.replies_moved),
    ambiguous: num(r.ambiguous_leads), no_date: num(r.sheet_rows_no_date), sample: r.sample,
  }))
  .sort((a, b) => b.to_move - a.to_move);
// A workbook that could not be read comes back as zero rows, not as an error — the read node is
// alwaysOutputData so one bad client cannot end the loop. That makes an empty read indistinguishable
// from an empty sheet unless it is counted: run 61572 read 4066 rows, 61605 read 5128 from the same
// 42 clients. Coverage has to be visible, or a partial run reads as a complete one.
const empty = ok.filter(r => num(r.sheet_rows) === 0).map(r => r.client);
return [{ json: {
  applied: ok.some(r => r.applied === true || r.applied === 'true'),
  clients: ok.length,
  clients_failed: errors.length,
  clients_empty: empty.length,
  empty_clients: empty,
  sheet_rows: total('sheet_rows'),
  sheet_rows_no_date: total('sheet_rows_no_date'),
  matched_leads: total('matched_leads'),
  ambiguous_leads: total('ambiguous_leads'),
  to_move: total('to_move'),
  to_move_aimfox: total('to_move_aimfox'),
  leads_moved: total('leads_moved'),
  replies_moved: total('replies_moved'),
  per_client: perClient,
} }];
